// facetResolver adapts the About projection into the buildFacets closure
// shape — the REAL naming.Namer.MetadataFor, the same resolver the api DTO
// seam serves About from (browse-scale OQ2). The library-aware signature
// lets one test feed per-library chains without a second resolver walk.
func facetResolver(chainByLib map[string]naming.Namer) func(string, json.RawMessage) map[string]any {
	return func(lib string, raw json.RawMessage) map[string]any {
		n, ok := chainByLib[lib]
		if !ok {
			return nil
		}
		return n.MetadataFor(raw)
	}
}

// TestFacetsMatchAboutResolver pins the facet↔About joint: the aggregates
// are exactly what the About resolver resolves WHOLE per document — the
// first effectively-enabled namespace carrying a description wins, its
// ride-along facts count, and nothing ever stitches from a later
// namespace (reviewer Q5: an earlier namespace carrying description but
// no genres contributes no genres, though a naive first-with-genres walk
// would find some). Table-driven over the REAL naming.Namer.MetadataFor.
func TestFacetsMatchAboutResolver(t *testing.T) {
	alpha := naming.TitleSourceBinding{ID: "alpha", Enabled: true}
	beta := naming.TitleSourceBinding{ID: "beta", Enabled: true}
	alphaOff := naming.TitleSourceBinding{ID: "alpha", Enabled: false}
	serialNamer := naming.Namer{Chain: []naming.TitleSourceBinding{alpha}}
	bothNamer := naming.Namer{Chain: []naming.TitleSourceBinding{alpha, beta}}
	betaWinsNamer := naming.Namer{Chain: []naming.TitleSourceBinding{alphaOff, beta}}
	filmNamer := naming.Namer{Chain: []naming.TitleSourceBinding{beta}}

	tests := []struct {
		name  string
		namer func(string) naming.Namer
		docs  map[string][]json.RawMessage
		want  map[string][]Facet
	}{
		{
			name: "winner wins whole: description carrier without genres contributes nothing",
			namer: func(string) naming.Namer {
				return bothNamer
			},
			docs: map[string][]json.RawMessage{"lib": {
				json.RawMessage(`{"sources":{"alpha":{"description":"the show"},"beta":{"description":"later","genres":["Drama","Horror"]}}}`),
			}},
			// alpha carries the synopsis group (description) but no genres:
			// beta's genres never stitch in — a naive first-with-genres walk
			// would count Drama and Horror here (the Q5 divergence).
			want: map[string][]Facet{"lib": {}},
		},
		{
			name: "ride-alongs count from each winner, count desc then value asc",
			namer: func(string) naming.Namer {
				return serialNamer
			},
			docs: map[string][]json.RawMessage{"lib": {
				json.RawMessage(`{"sources":{"alpha":{"description":"a","genres":["Action","Комедия","Drama"],"kind":"series","status":"continuing"}}}`),
				json.RawMessage(`{"sources":{"alpha":{"description":"b","genres":["Drama"],"kind":"series","status":"continuing"}}}`),
				json.RawMessage(`{"sources":{"alpha":{"description":"c","genres":["Drama","Action","Action"],"kind":"series","status":"continuing"}}}`),
			}},
			want: map[string][]Facet{"lib": {
				{Key: "genres", Values: []FacetValue{
					{Value: "Action", Count: 3},
					{Value: "Drama", Count: 3},
					{Value: "Комедия", Count: 1},
				}},
				{Key: "kind", Values: []FacetValue{{Value: "series", Count: 3}}},
				{Key: "status", Values: []FacetValue{{Value: "continuing", Count: 3}}},
			}},
		},
		{
			name: "gate-disabled source never wins a group",
			namer: func(string) naming.Namer {
				return betaWinsNamer
			},
			docs: map[string][]json.RawMessage{"lib": {
				json.RawMessage(`{"sources":{"alpha":{"description":"muted","genres":["Ghost"],"kind":"series"},"beta":{"description":"live","genres":["Real"],"kind":"film","status":"ended"}}}`),
			}},
			want: map[string][]Facet{"lib": {
				{Key: "genres", Values: []FacetValue{{Value: "Real", Count: 1}}},
				{Key: "kind", Values: []FacetValue{{Value: "film", Count: 1}}},
				{Key: "status", Values: []FacetValue{{Value: "ended", Count: 1}}},
			}},
		},
		{
			name: "facets counted per library under per-library chains",
			namer: func(lib string) naming.Namer {
				if lib == "films" {
					return filmNamer
				}
				return serialNamer
			},
			docs: map[string][]json.RawMessage{
				"serials": {
					json.RawMessage(`{"sources":{"alpha":{"description":"a","genres":["Drama"],"kind":"series"}}}`),
				},
				"films": {
					json.RawMessage(`{"sources":{"beta":{"description":"b","genres":["Horror"],"kind":"film"}}}`),
				},
			},
			want: map[string][]Facet{
				"serials": {
					{Key: "genres", Values: []FacetValue{{Value: "Drama", Count: 1}}},
					{Key: "kind", Values: []FacetValue{{Value: "series", Count: 1}}},
				},
				"films": {
					{Key: "genres", Values: []FacetValue{{Value: "Horror", Count: 1}}},
					{Key: "kind", Values: []FacetValue{{Value: "film", Count: 1}}},
				},
			},
		},
		{
			name: "unreadable and no-carrier documents contribute nothing",
			namer: func(string) naming.Namer {
				return serialNamer
			},
			docs: map[string][]json.RawMessage{"lib": {
				json.RawMessage(`not json`),
				json.RawMessage(`{"sources":{"alpha":{"cast":[{"name":"x"}]}}}`),
				json.RawMessage(`{"sources":{"alpha":{"description":"d","genres":["Only"]}}}`),
			}},
			want: map[string][]Facet{"lib": {
				{Key: "genres", Values: []FacetValue{{Value: "Only", Count: 1}}},
			}},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			namerByLib := map[string]naming.Namer{}
			for lib := range tt.docs {
				namerByLib[lib] = tt.namer(lib)
			}
			got := buildFacets(facetResolver(namerByLib), tt.docs)
			if !reflect.DeepEqual(got, tt.want) {
				t.Fatalf("buildFacets =\n\t%#v\nwant\n\t%#v", got, tt.want)
			}
		})
	}
}

// TestPhotoLibraryEmpty pins the photo-library case (D2): a library with
// no series documents — every photo library — maps to an empty non-nil
// facet list, the keys honestly absent, never a nil and never an error.
func TestPhotoLibraryEmpty(t *testing.T) {
	namer := map[string]naming.Namer{
		"photos": {Chain: []naming.TitleSourceBinding{{ID: "alpha", Enabled: true}}},
	}
	got := buildFacets(facetResolver(namer), map[string][]json.RawMessage{
		"photos": {},
	})
	f, ok := got["photos"]
	if !ok {
		t.Fatalf("photo library missing from the aggregate map: %#v", got)
	}
	if f == nil {
		t.Fatal("photo library facets = nil, want empty non-nil list")
	}
	if len(f) != 0 {
		t.Fatalf("photo library facets = %#v, want empty", f)
	}
}

// TestZeroCountOmitted pins the count-0 law (D2): values that appear in
// documents but never inside a winning About block resolve to count 0 —
// and a count-0 value is OMITTED from the served facet, never materialized
// as a zero entry. Every served value carries a positive count.
func TestZeroCountOmitted(t *testing.T) {
	namer := map[string]naming.Namer{
		"lib": {Chain: []naming.TitleSourceBinding{
			{ID: "alpha", Enabled: true},
			{ID: "beta", Enabled: true},
		}},
	}
	docs := map[string][]json.RawMessage{"lib": {
		// alpha wins the synopsis group; beta's facts never stitch in, so
		// Ghost/film/ended resolve to count 0 under the About semantics.
		json.RawMessage(`{"sources":{"alpha":{"description":"the show","genres":["Winner"],"kind":"series","status":"continuing"},"beta":{"description":"later","genres":["Ghost"],"kind":"film","status":"ended"}}}`),
	}}
	got := buildFacets(facetResolver(namer), docs)
	want := map[string][]Facet{"lib": {
		{Key: "genres", Values: []FacetValue{{Value: "Winner", Count: 1}}},
		{Key: "kind", Values: []FacetValue{{Value: "series", Count: 1}}},
		{Key: "status", Values: []FacetValue{{Value: "continuing", Count: 1}}},
	}}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("buildFacets =\n\t%#v\nwant\n\t%#v", got, want)
	}
	for _, f := range got["lib"] {
		for _, v := range f.Values {
			if v.Count <= 0 {
				t.Errorf("facet %s serves %q at count %d — count 0 must omit the value", f.Key, v.Value, v.Count)
			}
		}
	}
}
